import ExcelJS from 'exceljs';
import type { FinancialModelRecord } from '../src/types/financial';
import { buildSensitivityMatrix } from '../src/lib/financialModel';

const LEGAL_DISCLAIMER =
  'This analysis was generated by AI and is provided for informational purposes only. It does not constitute financial advice, investment recommendations, or an offer to buy or sell securities. Users should independently verify all data and consult with qualified financial advisors before making investment decisions.';

function colLetter(colNum: number): string {
  let letter = '';
  let n = colNum;
  while (n > 0) {
    const rem = (n - 1) % 26;
    letter = String.fromCharCode(65 + rem) + letter;
    n = Math.floor((n - 1) / 26);
  }
  return letter;
}

const FONT_HEADER: Partial<ExcelJS.Font> = { name: 'Calibri', size: 11, bold: true, color: { argb: 'FFFFFFFF' } };
const FONT_TITLE: Partial<ExcelJS.Font> = { name: 'Calibri', size: 14, bold: true, color: { argb: 'FF1A1A2E' } };
const FONT_SUBTITLE: Partial<ExcelJS.Font> = { name: 'Calibri', size: 10, italic: true, color: { argb: 'FF4B5563' } };
const FONT_INPUT: Partial<ExcelJS.Font> = { name: 'Calibri', size: 10, color: { argb: 'FF0000FF' } };
const FONT_FORMULA: Partial<ExcelJS.Font> = { name: 'Calibri', size: 10, color: { argb: 'FF111827' } };
const FONT_FORMULA_BOLD: Partial<ExcelJS.Font> = { name: 'Calibri', size: 10, bold: true, color: { argb: 'FF111827' } };
const FONT_LINK: Partial<ExcelJS.Font> = { name: 'Calibri', size: 10, color: { argb: 'FF008000' } };
const FONT_LINK_BOLD: Partial<ExcelJS.Font> = { name: 'Calibri', size: 10, bold: true, color: { argb: 'FF008000' } };

const FILL_NAVY: ExcelJS.Fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1A1A2E' } };
const FILL_SUBHEADER: ExcelJS.Fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE5E7EB' } };
const FILL_FORECAST_HEADER: ExcelJS.Fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1E3A8A' } };
const FILL_FORECAST_CELL: ExcelJS.Fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF0F7FF' } };

const BORDER_TOTAL: Partial<ExcelJS.Borders> = {
  top: { style: 'thin', color: { argb: 'FF9CA3AF' } },
  bottom: { style: 'double', color: { argb: 'FF111827' } },
};

const FMT_CURRENCY = '$#,##0.0;($#,##0.0);"-"';
const FMT_NUMBER = '#,##0.0;(#,##0.0);"-"';
const FMT_PRICE = '$#,##0.00;($#,##0.00);"-"';
const FMT_PCT = '0.0%';
const FMT_MULT = '0.0"x"';

export async function buildFinancialModelWorkbook(
  model: FinancialModelRecord,
  analystName: string,
  isFreeTier: boolean
): Promise<ExcelJS.Workbook> {
  const wb = new ExcelJS.Workbook();
  wb.creator = 'Fynance Bro';
  wb.created = new Date();
  wb.calcProperties.fullCalcOnLoad = true;

  const histIs = model.historical.incomeStatement;
  const fcstIs = model.forecast.incomeStatement;
  const allIs = [...histIs, ...fcstIs];

  const histBs = model.historical.balanceSheet;
  const fcstBs = model.forecast.balanceSheet;
  const allBs = [...histBs, ...fcstBs];

  const histCf = model.historical.cashFlow;
  const fcstCf = model.forecast.cashFlow;
  const allCf = [...histCf, ...fcstCf];

  const histLen = histIs.length;
  const totalYears = allIs.length;

  // =========================================================================
  // 1. COVER PAGE
  // =========================================================================
  const cover = wb.addWorksheet('Cover Page', { views: [{ showGridLines: false }] });
  cover.getColumn(1).width = 4;
  cover.getColumn(2).width = 28;
  cover.getColumn(3).width = 58;

  cover.getCell('B2').value = 'FYNANCE BRO — EQUITY RESEARCH & FINANCIAL MODEL';
  cover.getCell('B2').font = { name: 'Calibri', size: 16, bold: true, color: { argb: 'FF1A1A2E' } };
  cover.getCell('B3').value = `${model.companyInfo.companyName} (${model.companyInfo.exchange}: ${model.companyInfo.ticker})`;
  cover.getCell('B3').font = { name: 'Calibri', size: 13, bold: true, color: { argb: 'FF15803D' } };

  const coverRows: [string, string | number][] = [
    ['Sector / Industry', `${model.companyInfo.sector} — ${model.companyInfo.industry}`],
    ['Headquarters', model.companyInfo.headquarters],
    ['Chief Executive Officer', model.companyInfo.ceo],
    ['Fiscal Year End', model.companyInfo.fiscalYearEnd],
    ['Report Date', new Date().toISOString().slice(0, 10)],
    ['Prepared By', analystName],
    ['Currency Units', model.companyInfo.currencyUnit],
    ['Risk Profile', model.forecastConfig.riskProfile.toUpperCase()],
    ['Forecast Horizon', `${model.forecastConfig.horizonYears} Years`],
    ['Current Share Price', model.companyInfo.stockPrice],
    ['Model Status', model.status.toUpperCase()],
  ];

  coverRows.forEach(([k, v], idx) => {
    const r = 6 + idx;
    cover.getCell(r, 2).value = k;
    cover.getCell(r, 2).font = { name: 'Calibri', size: 10, bold: true, color: { argb: 'FF374151' } };
    cover.getCell(r, 3).value = v;
    cover.getCell(r, 3).font = { name: 'Calibri', size: 10, color: { argb: 'FF111827' } };
    if (k === 'Current Share Price') {
      cover.getCell(r, 3).numFmt = FMT_PRICE;
    }
    cover.getRow(r).border = { bottom: { style: 'hair', color: { argb: 'FFE5E7EB' } } };
  });

  // Color Legend
  cover.getCell('B19').value = 'MODEL COLOR CONVENTIONS';
  cover.getCell('B19').font = { name: 'Calibri', size: 11, bold: true, color: { argb: 'FF1A1A2E' } };
  cover.getCell('B20').value = 'Blue Font';
  cover.getCell('B20').font = FONT_INPUT;
  cover.getCell('C20').value = 'Hardcoded Historical Actuals & Editable Forecast Assumptions';
  cover.getCell('B21').value = 'Black Font';
  cover.getCell('B21').font = FONT_FORMULA;
  cover.getCell('C21').value = 'Same-Sheet Live Excel Formulas';
  cover.getCell('B22').value = 'Green Font';
  cover.getCell('B22').font = FONT_LINK;
  cover.getCell('C22').value = 'Cross-Sheet Formula Links';

  if (isFreeTier) {
    cover.getCell('B24').value = 'TIER NOTICE: Generated on Fynance Bro Free Tier (Upgrade to Pro for Clean Exports & PDF Reports)';
    cover.getCell('B24').font = { name: 'Calibri', size: 10, bold: true, color: { argb: 'FFB45309' } };
  }

  cover.getCell('B26').value = 'LEGAL DISCLAIMER';
  cover.getCell('B26').font = { name: 'Calibri', size: 10, bold: true, color: { argb: 'FF991B1B' } };
  cover.getCell('B27').value = LEGAL_DISCLAIMER;
  cover.getCell('B27').font = { name: 'Calibri', size: 9, italic: true, color: { argb: 'FF4B5563' } };
  cover.mergeCells('B27:C29');
  cover.getCell('B27').alignment = { wrapText: true, vertical: 'top' };

  // =========================================================================
  // 2. ASSUMPTIONS SHEET (Drives Forecast Years)
  // =========================================================================
  const assump = wb.addWorksheet('Assumptions', { views: [{ state: 'frozen', xSplit: 1, ySplit: 4 }] });
  assump.getColumn(1).width = 34;
  assump.getCell('A1').value = `${model.companyInfo.companyName} (${model.companyInfo.ticker}) — Forecast & Valuation Assumptions`;
  assump.getCell('A1').font = FONT_TITLE;
  assump.getCell('A2').value = `Units: ${model.companyInfo.currencyUnit} | Risk Profile: ${model.forecastConfig.riskProfile.toUpperCase()}`;
  assump.getCell('A2').font = FONT_SUBTITLE;

  assump.getCell('A4').value = 'Forecast Driver';
  assump.getCell('A4').font = FONT_HEADER;
  assump.getCell('A4').fill = FILL_NAVY;

  fcstIs.forEach((yr, idx) => {
    const c = idx + 2;
    assump.getColumn(c).width = 14;
    const cell = assump.getCell(4, c);
    cell.value = yr.year;
    cell.font = FONT_HEADER;
    cell.fill = FILL_FORECAST_HEADER;
    cell.alignment = { horizontal: 'right' };
  });

  // Rows on Assumptions sheet:
  // Row 5: Revenue Growth %
  // Row 6: Gross Margin %
  // Row 7: SG&A % of Revenue
  // Row 8: R&D % of Revenue
  // Row 9: D&A % of Revenue
  // Row 10: CapEx % of Revenue
  // Row 11: Effective Tax Rate
  // Row 12: Share Count Annual Factor
  const assumpLabels = [
    'Revenue Growth Rate (%)',
    'Gross Margin (%)',
    'SG&A (% of Revenue)',
    'R&D (% of Revenue)',
    'D&A (% of Revenue)',
    'CapEx (% of Revenue)',
    'Effective Tax Rate (%)',
    'Share Count Retention Factor',
  ];

  assumpLabels.forEach((lbl, idx) => {
    const r = 5 + idx;
    assump.getCell(r, 1).value = lbl;
    assump.getCell(r, 1).font = FONT_FORMULA;
  });

  fcstIs.forEach((yr, idx) => {
    const c = idx + 2;
    const prevRev = idx === 0 ? histIs[histIs.length - 1].revenue : fcstIs[idx - 1].revenue;
    const growth = prevRev > 0 ? (yr.revenue - prevRev) / prevRev : 0.05;
    const gm = yr.revenue > 0 ? yr.grossProfit / yr.revenue : 0.4;
    const sgaPct = yr.revenue > 0 ? yr.sga / yr.revenue : 0.1;
    const rdPct = yr.revenue > 0 ? yr.rd / yr.revenue : 0.05;
    const daPct = yr.revenue > 0 ? yr.da / yr.revenue : 0.04;
    const capexPct = yr.revenue > 0 ? fcstCf[idx].capex / yr.revenue : 0.05;
    const taxRate = yr.preTaxIncome > 0 ? yr.taxExpense / yr.preTaxIncome : 0.21;
    const prevShares = idx === 0 ? histIs[histIs.length - 1].sharesOutstanding : fcstIs[idx - 1].sharesOutstanding;
    const shareFactor = prevShares > 0 ? yr.sharesOutstanding / prevShares : 1;

    const vals = [growth, gm, sgaPct, rdPct, daPct, capexPct, taxRate, shareFactor];
    vals.forEach((v, rIdx) => {
      const cell = assump.getCell(5 + rIdx, c);
      cell.value = Number(v.toFixed(4));
      cell.font = FONT_INPUT;
      cell.numFmt = FMT_PCT;
      cell.fill = FILL_FORECAST_CELL;
    });
  });

  // Global Valuation Inputs block on Assumptions sheet (Column B, Rows 15-21)
  assump.getCell('A14').value = 'DCF & WACC Inputs';
  assump.getCell('A14').font = FONT_TITLE;

  const globalInputs: [string, number, string, string][] = [
    ['Risk-Free Rate', model.dcfInputs.riskFreeRate, FMT_PCT, 'Risk_Free_Rate'],
    ['Equity Beta', model.dcfInputs.beta, '0.00', 'Equity_Beta'],
    ['Equity Risk Premium', model.dcfInputs.equityRiskPremium, FMT_PCT, 'Equity_Risk_Premium'],
    ['Pre-Tax Cost of Debt', model.dcfOutput.costOfDebt, FMT_PCT, 'Cost_Of_Debt'],
    ['WACC Risk Adjustment (bps)', model.dcfInputs.waccAdjustmentBps / 10000, FMT_PCT, 'WACC_Adj'],
    ['Terminal Growth Rate', model.dcfOutput.terminalGrowthRate, FMT_PCT, 'Terminal_Growth'],
    ['Current Share Price', model.companyInfo.stockPrice, FMT_PRICE, 'Current_Price'],
  ];

  globalInputs.forEach(([label, val, fmt, name], idx) => {
    const r = 15 + idx;
    assump.getCell(r, 1).value = label;
    assump.getCell(r, 1).font = FONT_FORMULA;
    const cell = assump.getCell(r, 2);
    cell.value = val;
    cell.font = FONT_INPUT;
    cell.numFmt = fmt;
    wb.definedNames.add(`Assumptions!$B$${r}`, name);
  });

  // =========================================================================
  // 3. INCOME STATEMENT SHEET (Live Formulas)
  // =========================================================================
  const isSheet = wb.addWorksheet('Income Statement', { views: [{ state: 'frozen', xSplit: 1, ySplit: 4 }] });
  isSheet.getColumn(1).width = 32;
  isSheet.getCell('A1').value = `${model.companyInfo.companyName} (${model.companyInfo.ticker}) — Consolidated Income Statement`;
  isSheet.getCell('A1').font = FONT_TITLE;
  isSheet.getCell('A2').value = `In ${model.companyInfo.currencyUnit}, except per-share data`;
  assump.getCell('A2').font = FONT_SUBTITLE;

  isSheet.getCell('A4').value = 'Line Item';
  isSheet.getCell('A4').font = FONT_HEADER;
  isSheet.getCell('A4').fill = FILL_NAVY;

  allIs.forEach((yr, idx) => {
    const c = idx + 2;
    isSheet.getColumn(c).width = 15;
    const cell = isSheet.getCell(4, c);
    cell.value = yr.year;
    cell.font = FONT_HEADER;
    cell.fill = yr.isForecast ? FILL_FORECAST_HEADER : FILL_NAVY;
    cell.alignment = { horizontal: 'right' };
  });

  // Row mapping on Income Statement:
  // 5: Revenue
  // 6: Cost of Goods Sold (COGS)
  // 7: Gross Profit (=B5-B6)
  // 8: SG&A Expense
  // 9: R&D Expense
  // 10: Depreciation & Amortization (D&A)
  // 11: Operating Income (EBIT) (=B7-SUM(B8:B10))
  // 12: Interest Expense
  // 13: Pre-Tax Income (=B11-B12)
  // 14: Income Tax Expense
  // 15: Net Income (=B13-B14)
  // 16: EBITDA (=B11+B10)
  // 17: Diluted Shares (M)
  // 18: Diluted EPS (=B15/B17)
  const isLabels = [
    'Revenue',
    'Cost of Goods Sold (COGS)',
    'Gross Profit',
    'SG&A Expense',
    'Research & Development (R&D)',
    'Depreciation & Amortization (D&A)',
    'Operating Income (EBIT)',
    'Interest Expense',
    'Pre-Tax Income (EBT)',
    'Income Tax Expense',
    'Net Income',
    'EBITDA',
    'Diluted Shares Outstanding (M)',
    'Diluted EPS ($)',
  ];

  isLabels.forEach((lbl, idx) => {
    const r = 5 + idx;
    const cell = isSheet.getCell(r, 1);
    cell.value = lbl;
    const isTotal = [7, 11, 13, 15, 16, 18].includes(r);
    cell.font = isTotal ? FONT_FORMULA_BOLD : FONT_FORMULA;
  });

  allIs.forEach((yr, idx) => {
    const c = idx + 2;
    const col = colLetter(c);
    const prevCol = colLetter(c - 1);
    const isFcst = idx >= histLen;
    const fcstCol = colLetter(idx - histLen + 2);

    const setCell = (
      row: number,
      val: number | { formula: string; result: number },
      font: Partial<ExcelJS.Font>,
      fmt: string,
      totalBorder = false
    ) => {
      const cell = isSheet.getCell(row, c);
      cell.value = val;
      cell.font = font;
      cell.numFmt = fmt;
      if (isFcst) cell.fill = FILL_FORECAST_CELL;
      if (totalBorder) cell.border = BORDER_TOTAL;
    };

    if (!isFcst) {
      // Historical inputs in blue, derived totals as live black formulas
      setCell(5, yr.revenue, FONT_INPUT, FMT_CURRENCY);
      setCell(6, yr.cogs, FONT_INPUT, FMT_CURRENCY);
      setCell(7, { formula: `${col}5-${col}6`, result: yr.grossProfit }, FONT_FORMULA_BOLD, FMT_CURRENCY, true);
      setCell(8, yr.sga, FONT_INPUT, FMT_CURRENCY);
      setCell(9, yr.rd, FONT_INPUT, FMT_CURRENCY);
      setCell(10, yr.da, FONT_INPUT, FMT_CURRENCY);
      setCell(11, { formula: `${col}7-SUM(${col}8:${col}10)`, result: yr.ebit }, FONT_FORMULA_BOLD, FMT_CURRENCY, true);
      setCell(12, yr.interestExpense, FONT_INPUT, FMT_CURRENCY);
      setCell(13, { formula: `${col}11-${col}12`, result: yr.preTaxIncome }, FONT_FORMULA_BOLD, FMT_CURRENCY);
      setCell(14, yr.taxExpense, FONT_INPUT, FMT_CURRENCY);
      setCell(15, { formula: `${col}13-${col}14`, result: yr.netIncome }, FONT_FORMULA_BOLD, FMT_CURRENCY, true);
      setCell(16, { formula: `${col}11+${col}10`, result: yr.ebitda }, FONT_FORMULA_BOLD, FMT_CURRENCY);
      setCell(17, yr.sharesOutstanding, FONT_INPUT, FMT_NUMBER);
      setCell(18, { formula: `${col}15/${col}17`, result: yr.epsDiluted }, FONT_FORMULA_BOLD, FMT_PRICE, true);
    } else {
      // Forecast columns link back to Assumptions tab!
      setCell(
        5,
        { formula: `${prevCol}5*(1+Assumptions!${fcstCol}5)`, result: yr.revenue },
        FONT_LINK_BOLD,
        FMT_CURRENCY
      );
      setCell(
        6,
        { formula: `${col}5*(1-Assumptions!${fcstCol}6)`, result: yr.cogs },
        FONT_LINK,
        FMT_CURRENCY
      );
      setCell(7, { formula: `${col}5-${col}6`, result: yr.grossProfit }, FONT_FORMULA_BOLD, FMT_CURRENCY, true);
      setCell(8, { formula: `${col}5*Assumptions!${fcstCol}7`, result: yr.sga }, FONT_LINK, FMT_CURRENCY);
      setCell(9, { formula: `${col}5*Assumptions!${fcstCol}8`, result: yr.rd }, FONT_LINK, FMT_CURRENCY);
      setCell(10, { formula: `${col}5*Assumptions!${fcstCol}9`, result: yr.da }, FONT_LINK, FMT_CURRENCY);
      setCell(11, { formula: `${col}7-SUM(${col}8:${col}10)`, result: yr.ebit }, FONT_FORMULA_BOLD, FMT_CURRENCY, true);
      setCell(12, { formula: `${prevCol}12`, result: yr.interestExpense }, FONT_FORMULA, FMT_CURRENCY);
      setCell(13, { formula: `${col}11-${col}12`, result: yr.preTaxIncome }, FONT_FORMULA_BOLD, FMT_CURRENCY);
      setCell(
        14,
        { formula: `MAX(0,${col}13*Assumptions!${fcstCol}11)`, result: yr.taxExpense },
        FONT_LINK,
        FMT_CURRENCY
      );
      setCell(15, { formula: `${col}13-${col}14`, result: yr.netIncome }, FONT_FORMULA_BOLD, FMT_CURRENCY, true);
      setCell(16, { formula: `${col}11+${col}10`, result: yr.ebitda }, FONT_FORMULA_BOLD, FMT_CURRENCY);
      setCell(
        17,
        { formula: `${prevCol}17*Assumptions!${fcstCol}12`, result: yr.sharesOutstanding },
        FONT_LINK,
        FMT_NUMBER
      );
      setCell(18, { formula: `${col}15/${col}17`, result: yr.epsDiluted }, FONT_FORMULA_BOLD, FMT_PRICE, true);
    }
  });

  // =========================================================================
  // 4. BALANCE SHEET (Live Formulas)
  // =========================================================================
  const bsSheet = wb.addWorksheet('Balance Sheet', { views: [{ state: 'frozen', xSplit: 1, ySplit: 4 }] });
  bsSheet.getColumn(1).width = 32;
  bsSheet.getCell('A1').value = `${model.companyInfo.companyName} (${model.companyInfo.ticker}) — Consolidated Balance Sheet`;
  bsSheet.getCell('A1').font = FONT_TITLE;
  bsSheet.getCell('A2').value = `In ${model.companyInfo.currencyUnit}`;
  bsSheet.getCell('A2').font = FONT_SUBTITLE;

  bsSheet.getCell('A4').value = 'Balance Sheet Item';
  bsSheet.getCell('A4').font = FONT_HEADER;
  bsSheet.getCell('A4').fill = FILL_NAVY;

  allBs.forEach((yr, idx) => {
    const c = idx + 2;
    bsSheet.getColumn(c).width = 15;
    const cell = bsSheet.getCell(4, c);
    cell.value = yr.year;
    cell.font = FONT_HEADER;
    cell.fill = yr.isForecast ? FILL_FORECAST_HEADER : FILL_NAVY;
    cell.alignment = { horizontal: 'right' };
  });

  const bsLabels = [
    'Cash & Equivalents',
    'Accounts Receivable',
    'Inventory',
    'Total Current Assets',
    'Property, Plant & Equipment (Net)',
    'Goodwill',
    'Intangible Assets',
    'Total Assets',
    'Accounts Payable',
    'Short-Term Debt',
    'Total Current Liabilities',
    'Long-Term Debt',
    'Total Liabilities',
    'Shareholders Equity',
  ];

  bsLabels.forEach((lbl, idx) => {
    const r = 5 + idx;
    bsSheet.getCell(r, 1).value = lbl;
    const isTotal = [8, 12, 15, 17, 18].includes(r);
    bsSheet.getCell(r, 1).font = isTotal ? FONT_FORMULA_BOLD : FONT_FORMULA;
  });

  allBs.forEach((yr, idx) => {
    const c = idx + 2;
    const col = colLetter(c);
    const isFcst = idx >= histLen;

    const setBs = (
      row: number,
      val: number | { formula: string; result: number },
      font: Partial<ExcelJS.Font>,
      totalBorder = false
    ) => {
      const cell = bsSheet.getCell(row, c);
      cell.value = val;
      cell.font = font;
      cell.numFmt = FMT_CURRENCY;
      if (isFcst) cell.fill = FILL_FORECAST_CELL;
      if (totalBorder) cell.border = BORDER_TOTAL;
    };

    setBs(5, yr.cashAndEquivalents, FONT_INPUT);
    setBs(6, yr.accountsReceivable, FONT_INPUT);
    setBs(7, yr.inventory, FONT_INPUT);
    setBs(8, { formula: `SUM(${col}5:${col}7)`, result: yr.totalCurrentAssets }, FONT_FORMULA_BOLD, true);
    setBs(9, yr.ppeNet, FONT_INPUT);
    setBs(10, yr.goodwill, FONT_INPUT);
    setBs(11, yr.intangibles, FONT_INPUT);
    setBs(12, { formula: `${col}8+SUM(${col}9:${col}11)`, result: yr.totalAssets }, FONT_FORMULA_BOLD, true);
    setBs(13, yr.accountsPayable, FONT_INPUT);
    setBs(14, yr.shortTermDebt, FONT_INPUT);
    setBs(15, { formula: `SUM(${col}13:${col}14)`, result: yr.totalCurrentLiabilities }, FONT_FORMULA_BOLD, true);
    setBs(16, yr.longTermDebt, FONT_INPUT);
    setBs(17, { formula: `${col}15+${col}16`, result: yr.totalLiabilities }, FONT_FORMULA_BOLD, true);
    setBs(18, yr.shareholdersEquity, FONT_INPUT, true);
  });

  // =========================================================================
  // 5. CASH FLOW STATEMENT (Live Formulas)
  // =========================================================================
  const cfSheet = wb.addWorksheet('Cash Flow Statement', { views: [{ state: 'frozen', xSplit: 1, ySplit: 4 }] });
  cfSheet.getColumn(1).width = 32;
  cfSheet.getCell('A1').value = `${model.companyInfo.companyName} (${model.companyInfo.ticker}) — Consolidated Cash Flow Statement`;
  cfSheet.getCell('A1').font = FONT_TITLE;
  cfSheet.getCell('A2').value = `In ${model.companyInfo.currencyUnit}`;
  cfSheet.getCell('A2').font = FONT_SUBTITLE;

  cfSheet.getCell('A4').value = 'Cash Flow Item';
  cfSheet.getCell('A4').font = FONT_HEADER;
  cfSheet.getCell('A4').fill = FILL_NAVY;

  allCf.forEach((yr, idx) => {
    const c = idx + 2;
    cfSheet.getColumn(c).width = 15;
    const cell = cfSheet.getCell(4, c);
    cell.value = yr.year;
    cell.font = FONT_HEADER;
    cell.fill = yr.isForecast ? FILL_FORECAST_HEADER : FILL_NAVY;
    cell.alignment = { horizontal: 'right' };
  });

  const cfLabels = [
    'Cash Flow from Operations (CFO)',
    'Capital Expenditures (CapEx)',
    'Free Cash Flow (FCF)',
    'Acquisitions',
    'Dividends Paid',
    'Share Repurchases',
    'Debt Issuance / (Repayment)',
    'Net Change in Cash',
  ];

  cfLabels.forEach((lbl, idx) => {
    const r = 5 + idx;
    cfSheet.getCell(r, 1).value = lbl;
    cfSheet.getCell(r, 1).font = [7, 12].includes(r) ? FONT_FORMULA_BOLD : FONT_FORMULA;
  });

  allCf.forEach((yr, idx) => {
    const c = idx + 2;
    const col = colLetter(c);
    const isFcst = idx >= histLen;
    const fcstCol = colLetter(idx - histLen + 2);

    const setCf = (
      row: number,
      val: number | { formula: string; result: number },
      font: Partial<ExcelJS.Font>,
      totalBorder = false
    ) => {
      const cell = cfSheet.getCell(row, c);
      cell.value = val;
      cell.font = font;
      cell.numFmt = FMT_CURRENCY;
      if (isFcst) cell.fill = FILL_FORECAST_CELL;
      if (totalBorder) cell.border = BORDER_TOTAL;
    };

    setCf(5, yr.cfo, FONT_INPUT);
    if (!isFcst) {
      setCf(6, yr.capex, FONT_INPUT);
    } else {
      setCf(
        6,
        { formula: `'Income Statement'!${col}5*Assumptions!${fcstCol}10`, result: yr.capex },
        FONT_LINK
      );
    }
    setCf(7, { formula: `${col}5-${col}6`, result: yr.fcf }, FONT_FORMULA_BOLD, true);
    setCf(8, yr.acquisitions, FONT_INPUT);
    setCf(9, yr.dividends, FONT_INPUT);
    setCf(10, yr.shareRepurchases, FONT_INPUT);
    setCf(11, yr.debtIssuanceRepayment, FONT_INPUT);
    setCf(
      12,
      { formula: `${col}7-${col}8-${col}9-${col}10+${col}11`, result: yr.netChangeInCash },
      FONT_FORMULA_BOLD,
      true
    );
  });

  // =========================================================================
  // 6. DCF MODEL SHEET (Live WACC, UFCF, Terminal Value, EV, Share Price)
  // =========================================================================
  const dcfSheet = wb.addWorksheet('DCF Model', { views: [{ state: 'frozen', xSplit: 1, ySplit: 4 }] });
  dcfSheet.getColumn(1).width = 34;
  dcfSheet.getCell('A1').value = `${model.companyInfo.companyName} (${model.companyInfo.ticker}) — Discounted Cash Flow Valuation`;
  dcfSheet.getCell('A1').font = FONT_TITLE;
  dcfSheet.getCell('A2').value = `In ${model.companyInfo.currencyUnit}, except per-share data`;
  dcfSheet.getCell('A2').font = FONT_SUBTITLE;

  // WACC Build (Rows 4-13, Columns A-B)
  dcfSheet.getColumn(2).width = 18;
  dcfSheet.getCell('A4').value = 'WACC Calculation';
  dcfSheet.getCell('A4').font = FONT_HEADER;
  dcfSheet.getCell('A4').fill = FILL_NAVY;
  dcfSheet.getCell('B4').value = 'Value';
  dcfSheet.getCell('B4').font = FONT_HEADER;
  dcfSheet.getCell('B4').fill = FILL_NAVY;
  dcfSheet.getCell('B4').alignment = { horizontal: 'right' };

  const lastHistBsCol = colLetter(histLen + 1);
  const lastHistIsCol = colLetter(histLen + 1);

  const waccRows: [string, { formula: string; result: number }, string, Partial<ExcelJS.Font>][] = [
    ['Risk-Free Rate', { formula: 'Assumptions!B15', result: model.dcfInputs.riskFreeRate }, FMT_PCT, FONT_LINK],
    ['Beta', { formula: 'Assumptions!B16', result: model.dcfInputs.beta }, '0.00', FONT_LINK],
    ['Equity Risk Premium', { formula: 'Assumptions!B17', result: model.dcfInputs.equityRiskPremium }, FMT_PCT, FONT_LINK],
    ['Cost of Equity (CAPM)', { formula: 'B5+B6*B7', result: model.dcfOutput.costOfEquity }, FMT_PCT, FONT_FORMULA_BOLD],
    ['Pre-Tax Cost of Debt', { formula: 'Assumptions!B18', result: model.dcfOutput.costOfDebt }, FMT_PCT, FONT_LINK],
    ['Effective Tax Rate', { formula: 'Assumptions!B11', result: model.dcfOutput.effectiveTaxRate }, FMT_PCT, FONT_LINK],
    ['After-Tax Cost of Debt', { formula: 'B9*(1-B10)', result: model.dcfOutput.afterTaxCostOfDebt }, FMT_PCT, FONT_FORMULA],
    ['Equity Weight (E/V)', { formula: `(${model.dcfOutput.equityWeight})`, result: model.dcfOutput.equityWeight }, FMT_PCT, FONT_INPUT],
    ['Debt Weight (D/V)', { formula: '1-B12', result: model.dcfOutput.debtWeight }, FMT_PCT, FONT_FORMULA],
    ['WACC (Risk-Adjusted)', { formula: 'B8*B12+B11*B13+Assumptions!B19', result: model.dcfOutput.wacc }, FMT_PCT, FONT_FORMULA_BOLD],
    ['Terminal Growth Rate', { formula: 'Assumptions!B20', result: model.dcfOutput.terminalGrowthRate }, FMT_PCT, FONT_LINK],
  ];

  waccRows.forEach(([lbl, f, fmt, font], idx) => {
    const r = 5 + idx;
    dcfSheet.getCell(r, 1).value = lbl;
    dcfSheet.getCell(r, 1).font = lbl.includes('WACC') || lbl.includes('Cost of Equity') ? FONT_FORMULA_BOLD : FONT_FORMULA;
    const cell = dcfSheet.getCell(r, 2);
    cell.value = f;
    cell.font = font;
    cell.numFmt = fmt;
    if (r === 14) cell.border = BORDER_TOTAL;
  });

  wb.definedNames.add("'DCF Model'!$B$14", 'WACC');
  wb.definedNames.add("'DCF Model'!$B$15", 'Terminal_Growth');

  // Unlevered FCF Table (Rows 18-26)
  dcfSheet.getCell('A18').value = 'Unlevered Free Cash Flow Schedule';
  dcfSheet.getCell('A18').font = FONT_HEADER;
  dcfSheet.getCell('A18').fill = FILL_NAVY;

  model.dcfOutput.projectedFcfs.forEach((yr, idx) => {
    const c = idx + 2;
    dcfSheet.getColumn(c).width = 16;
    const cell = dcfSheet.getCell(18, c);
    cell.value = yr.year;
    cell.font = FONT_HEADER;
    cell.fill = FILL_FORECAST_HEADER;
    cell.alignment = { horizontal: 'right' };
  });

  const ufcfLabels = [
    'EBIT',
    'Less: Taxes on EBIT (NOPAT Tax)',
    'NOPAT',
    'Plus: D&A',
    'Less: CapEx',
    'Less: Change in NWC',
    'Unlevered Free Cash Flow (UFCF)',
    'Discount Period (Years)',
    'Present Value of UFCF',
  ];
  ufcfLabels.forEach((lbl, idx) => {
    const r = 19 + idx;
    dcfSheet.getCell(r, 1).value = lbl;
    dcfSheet.getCell(r, 1).font = [21, 25, 27].includes(r) ? FONT_FORMULA_BOLD : FONT_FORMULA;
  });

  model.dcfOutput.projectedFcfs.forEach((yr, idx) => {
    const c = idx + 2;
    const col = colLetter(c);
    const isCol = colLetter(histLen + idx + 2);

    const setDcf = (row: number, val: number | { formula: string; result: number }, font: Partial<ExcelJS.Font>, fmt = FMT_CURRENCY, border = false) => {
      const cell = dcfSheet.getCell(row, c);
      cell.value = val;
      cell.font = font;
      cell.numFmt = fmt;
      cell.fill = FILL_FORECAST_CELL;
      if (border) cell.border = BORDER_TOTAL;
    };

    setDcf(19, { formula: `'Income Statement'!${isCol}11`, result: yr.ebit }, FONT_LINK);
    setDcf(20, { formula: `${col}19*$B$10`, result: yr.ebit - yr.nopat }, FONT_FORMULA);
    setDcf(21, { formula: `${col}19-${col}20`, result: yr.nopat }, FONT_FORMULA_BOLD, FMT_CURRENCY, true);
    setDcf(22, { formula: `'Income Statement'!${isCol}10`, result: yr.da }, FONT_LINK);
    setDcf(23, { formula: `'Cash Flow Statement'!${isCol}6`, result: yr.capex }, FONT_LINK);
    setDcf(24, yr.deltaNwc, FONT_INPUT);
    setDcf(25, { formula: `${col}21+${col}22-${col}23-${col}24`, result: yr.ufcf }, FONT_FORMULA_BOLD, FMT_CURRENCY, true);
    setDcf(26, idx + 1, FONT_INPUT, '0');
    setDcf(27, { formula: `${col}25/((1+$B$14)^${col}26)`, result: yr.pvOfFcf }, FONT_FORMULA_BOLD, FMT_CURRENCY, true);
  });

  // Enterprise & Equity Value Bridge (Rows 30-39)
  const lastUfcfCol = colLetter(model.dcfOutput.projectedFcfs.length + 1);
  dcfSheet.getCell('A30').value = 'Valuation Bridge';
  dcfSheet.getCell('A30').font = FONT_HEADER;
  dcfSheet.getCell('A30').fill = FILL_NAVY;
  dcfSheet.getCell('B30').value = 'Output';
  dcfSheet.getCell('B30').font = FONT_HEADER;
  dcfSheet.getCell('B30').fill = FILL_NAVY;
  dcfSheet.getCell('B30').alignment = { horizontal: 'right' };

  const bridgeRows: [string, { formula: string; result: number }, string, Partial<ExcelJS.Font>, boolean][] = [
    ['Sum of PV of Projected UFCFs', { formula: `SUM(B27:${lastUfcfCol}27)`, result: model.dcfOutput.sumPvOfFcfs }, FMT_CURRENCY, FONT_FORMULA, false],
    ['Terminal Value (Gordon Growth)', { formula: `(${lastUfcfCol}25*(1+$B$15))/($B$14-$B$15)`, result: model.dcfOutput.terminalValue }, FMT_CURRENCY, FONT_FORMULA, false],
    ['Present Value of Terminal Value', { formula: `B32/((1+$B$14)^${lastUfcfCol}26)`, result: model.dcfOutput.pvOfTerminalValue }, FMT_CURRENCY, FONT_FORMULA, false],
    ['Implied Enterprise Value (EV)', { formula: 'B31+B33', result: model.dcfOutput.enterpriseValue }, FMT_CURRENCY, FONT_FORMULA_BOLD, true],
    ['Less: Total Debt', { formula: `'Balance Sheet'!${lastHistBsCol}14+'Balance Sheet'!${lastHistBsCol}16`, result: model.dcfOutput.totalDebt }, FMT_CURRENCY, FONT_LINK, false],
    ['Plus: Cash & Equivalents', { formula: `'Balance Sheet'!${lastHistBsCol}5`, result: model.dcfOutput.cashAndEquivalents }, FMT_CURRENCY, FONT_LINK, false],
    ['Implied Equity Value', { formula: 'B34-B35+B36', result: model.dcfOutput.equityValue }, FMT_CURRENCY, FONT_FORMULA_BOLD, true],
    ['Diluted Shares Outstanding (M)', { formula: `'Income Statement'!${lastHistIsCol}17`, result: model.dcfOutput.dilutedShares }, FMT_NUMBER, FONT_LINK, false],
    ['Implied Share Price ($)', { formula: 'B37/B38', result: model.dcfOutput.impliedSharePrice }, FMT_PRICE, FONT_FORMULA_BOLD, true],
    ['Upside / (Downside) vs Current Price', { formula: '(B39-Assumptions!B21)/Assumptions!B21', result: model.dcfOutput.upsideDownsidePct }, FMT_PCT, FONT_FORMULA_BOLD, false],
  ];

  bridgeRows.forEach(([lbl, f, fmt, font, border], idx) => {
    const r = 31 + idx;
    dcfSheet.getCell(r, 1).value = lbl;
    dcfSheet.getCell(r, 1).font = border ? FONT_FORMULA_BOLD : FONT_FORMULA;
    const cell = dcfSheet.getCell(r, 2);
    cell.value = f;
    cell.font = font;
    cell.numFmt = fmt;
    if (border) cell.border = BORDER_TOTAL;
  });

  // =========================================================================
  // 7. SENSITIVITY SHEET (Dynamic Formulas referencing DCF Model)
  // =========================================================================
  const sensSheet = wb.addWorksheet('Sensitivity', { views: [{ state: 'frozen', xSplit: 1, ySplit: 4 }] });
  sensSheet.getColumn(1).width = 24;
  sensSheet.getCell('A1').value = `${model.companyInfo.companyName} (${model.companyInfo.ticker}) — Sensitivity Analysis (Implied Share Price)`;
  sensSheet.getCell('A1').font = FONT_TITLE;
  sensSheet.getCell('A2').value = 'Y-Axis: WACC (6.0% – 12.0%) vs X-Axis: Terminal Growth Rate (1.0% – 4.0%)';
  sensSheet.getCell('A2').font = FONT_SUBTITLE;

  const sensMatrix = buildSensitivityMatrix(
    'wacc_tgr',
    model.companyInfo,
    model.historical,
    model.forecastConfig,
    model.forecast,
    model.dcfInputs,
    model.dcfOutput
  );

  sensSheet.getCell('A4').value = 'WACC \\ Terminal Growth';
  sensSheet.getCell('A4').font = FONT_HEADER;
  sensSheet.getCell('A4').fill = FILL_NAVY;

  sensMatrix.xValues.forEach((xVal, xIdx) => {
    const c = xIdx + 2;
    sensSheet.getColumn(c).width = 14;
    const cell = sensSheet.getCell(4, c);
    cell.value = xVal;
    cell.font = FONT_HEADER;
    cell.fill = FILL_FORECAST_HEADER;
    cell.numFmt = FMT_PCT;
    cell.alignment = { horizontal: 'right' };
  });

  const numProj = model.dcfOutput.projectedFcfs.length;
  const lastProjCol = colLetter(numProj + 1);

  sensMatrix.yValues.forEach((yVal, yIdx) => {
    const r = 5 + yIdx;
    const rowHeader = sensSheet.getCell(r, 1);
    rowHeader.value = yVal;
    rowHeader.font = FONT_FORMULA_BOLD;
    rowHeader.fill = FILL_SUBHEADER;
    rowHeader.numFmt = FMT_PCT;

    sensMatrix.xValues.forEach((_xVal, xIdx) => {
      const c = xIdx + 2;
      const col = colLetter(c);
      const cellData = sensMatrix.cells[yIdx][xIdx];
      // Live dynamic formula computing implied share price for each (WACC, TGR) pair!
      const pvTerms = Array.from({ length: numProj }, (_, k) => {
        const dCol = colLetter(k + 2);
        return `('DCF Model'!$${dCol}$25/((1+$A${r})^${k + 1}))`;
      }).join('+');
      const formula = `((${pvTerms}+((('DCF Model'!$${lastProjCol}$25*(1+${col}$4))/($A${r}-${col}$4))/((1+$A${r})^${numProj})))-'DCF Model'!$B$35+'DCF Model'!$B$36)/'DCF Model'!$B$38`;

      const cell = sensSheet.getCell(r, c);
      cell.value = { formula, result: cellData.impliedPrice };
      cell.font = cellData.isBase ? FONT_FORMULA_BOLD : FONT_FORMULA;
      cell.numFmt = FMT_PRICE;

      if (cellData.bucket === 'upside') {
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFD1FAE5' } };
      } else if (cellData.bucket === 'downside') {
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFEE2E2' } };
      } else {
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFEF3C7' } };
      }
      if (cellData.isBase) {
        cell.border = {
          top: { style: 'medium', color: { argb: 'FF1A1A2E' } },
          bottom: { style: 'medium', color: { argb: 'FF1A1A2E' } },
          left: { style: 'medium', color: { argb: 'FF1A1A2E' } },
          right: { style: 'medium', color: { argb: 'FF1A1A2E' } },
        };
      }
    });
  });

  // =========================================================================
  // 8. KEY RATIOS SHEET (Live Cross-Sheet Formulas)
  // =========================================================================
  const ratioSheet = wb.addWorksheet('Key Ratios', { views: [{ state: 'frozen', xSplit: 1, ySplit: 4 }] });
  ratioSheet.getColumn(1).width = 32;
  ratioSheet.getCell('A1').value = `${model.companyInfo.companyName} (${model.companyInfo.ticker}) — Key Financial Ratios`;
  ratioSheet.getCell('A1').font = FONT_TITLE;
  ratioSheet.getCell('A2').value = 'All ratios linked dynamically to Income Statement & Balance Sheet';
  ratioSheet.getCell('A2').font = FONT_SUBTITLE;

  ratioSheet.getCell('A4').value = 'Metric';
  ratioSheet.getCell('A4').font = FONT_HEADER;
  ratioSheet.getCell('A4').fill = FILL_NAVY;

  allIs.forEach((yr, idx) => {
    const c = idx + 2;
    ratioSheet.getColumn(c).width = 14;
    const cell = ratioSheet.getCell(4, c);
    cell.value = yr.year;
    cell.font = FONT_HEADER;
    cell.fill = yr.isForecast ? FILL_FORECAST_HEADER : FILL_NAVY;
    cell.alignment = { horizontal: 'right' };
  });

  const allRatios = [...model.historical.ratios, ...model.forecast.ratios];
  const ratioRows = [
    'Revenue Growth (YoY)',
    'Gross Margin',
    'Operating Margin (EBIT)',
    'EBITDA Margin',
    'Net Profit Margin',
    'Return on Equity (ROE)',
    'Return on Assets (ROA)',
    'Current Ratio (x)',
    'Debt / Equity (x)',
  ];
  ratioRows.forEach((lbl, idx) => {
    ratioSheet.getCell(5 + idx, 1).value = lbl;
    ratioSheet.getCell(5 + idx, 1).font = FONT_FORMULA;
  });

  allRatios.forEach((rData, idx) => {
    const c = idx + 2;
    const col = colLetter(c);
    const prevCol = colLetter(c - 1);
    const isFcst = idx >= histLen;

    const setR = (row: number, val: number | string | { formula: string; result: number }, fmt: string) => {
      const cell = ratioSheet.getCell(row, c);
      cell.value = val;
      cell.font = typeof val === 'object' ? FONT_LINK : FONT_FORMULA;
      cell.numFmt = fmt;
      if (isFcst) cell.fill = FILL_FORECAST_CELL;
    };

    if (idx === 0) {
      setR(5, '—', '@');
    } else {
      setR(
        5,
        {
          formula: `('Income Statement'!${col}5-'Income Statement'!${prevCol}5)/'Income Statement'!${prevCol}5`,
          result: rData.revenueGrowthYoY ?? 0,
        },
        FMT_PCT
      );
    }
    setR(6, { formula: `'Income Statement'!${col}7/'Income Statement'!${col}5`, result: rData.grossMargin }, FMT_PCT);
    setR(7, { formula: `'Income Statement'!${col}11/'Income Statement'!${col}5`, result: rData.operatingMargin }, FMT_PCT);
    setR(8, { formula: `'Income Statement'!${col}16/'Income Statement'!${col}5`, result: rData.ebitdaMargin }, FMT_PCT);
    setR(9, { formula: `'Income Statement'!${col}15/'Income Statement'!${col}5`, result: rData.netMargin }, FMT_PCT);
    setR(10, { formula: `'Income Statement'!${col}15/'Balance Sheet'!${col}18`, result: rData.roe }, FMT_PCT);
    setR(11, { formula: `'Income Statement'!${col}15/'Balance Sheet'!${col}12`, result: rData.roa }, FMT_PCT);
    setR(12, { formula: `'Balance Sheet'!${col}8/'Balance Sheet'!${col}15`, result: rData.currentRatio }, FMT_MULT);
    setR(13, { formula: `('Balance Sheet'!${col}14+'Balance Sheet'!${col}16)/'Balance Sheet'!${col}18`, result: rData.debtToEquity }, FMT_MULT);
  });

  // Page setup across sheets for clean printing
  wb.worksheets.forEach((ws) => {
    ws.pageSetup = { orientation: 'landscape', fitToPage: true, fitToWidth: 1, fitToHeight: 0 };
  });

  return wb;
}
